            { t = "Morning. My trumpets are open and full of dew. A good hour for a clear head and a clear page.", when = { hour = "morning" } },
            { t = "The early light comes up thin and kind. I have watched the sun rise over a great many gardens. This is a good one.", when = { hour = "morning" } },
            { t = "Midday. The bees go in plain and come out gold to the knees. Read in the shade, child. I will stand in the sun for us both.", when = { hour = "day" } },
