            { t = "Spring. My stem rises a little every day. I do not rush. June will come whether I hurry or not.", when = { season = "spring" } },
            { t = "Everything in the garden is shouting about spring. I prefer to say a thing once, when I am ready.", when = { season = "spring" } },
            { t = "Early summer, and my flowers are open. Let the garden come to me. The garden always does.", when = { season = "summer" } },
