        level = {
            { t = "I have begun to look for you at the gate each evening. At my age one does not look for many people.", when = { level = 2, max_level = 2 } },
            { t = "You speak softly near me. I noticed from the start, and I have liked you since that first quiet hello.", when = { level = 2, max_level = 2 } },
            { t = "I let the bees in first, always. Lately I find I would let you in before the bees.", when = { level = 2, max_level = 2 } },
            { t = "A thing I seldom tell: I have not always been calm. Calm is something I learned, a century at a time.", when = { level = 3, max_level = 3 } },
            { t = "You have seen me with no flowers at all, only leaves on the ground, and still you came. I keep a list of such people. A short list.", when = { level = 3, max_level = 3 } },
            { t = "I have stood beside kings and saints in paintings. I would rather stand beside you in this plain garden.", when = { level = 3, max_level = 3 } },
            { t = "A secret, child: once I thought the last reader I would ever know had gone. I was wrong. I am so seldom wrong that I am enjoying this.", when = { level = 4, max_level = 4 } },
