    beats = {
        { id = "wall", at = 15, title = "The painted wall",
            text = "The first thing I remember is older than me: wet plaster, a white wall by the sea, and a painter humming as he laid down lilies in red and white. That was Crete, three thousand years ago and more. The palace fell long since. I still know the tune." },
        { id = "handed", at = 40, title = "Handed on",
            text = "We lilies hardly ever set seed. A scale is broken from the bulb and planted, and grows into a lily, and so on down the years. I am a piece of a piece of a piece. That is why I remember, faintly, things no single flower could." },
        { id = "ship", at = 80, title = "The ship",
            text = "Some of us went to sea in baskets of earth, wedged between jars of oil. I remember salt on the petals, and a sailor who watered us before he drank. Lilies have crossed more water than most queens." },
        { id = "cloister", at = 140, title = "The cloister",
            text = "For a long while I lived in a monastery yard, by a bench where a monk copied books by hand. In June my scent drifted over his pages. I like to think some old book somewhere still smells faintly of lily, and nobody knows why." },
        { id = "painter", at = 220, title = "The painter",
            text = "A young painter once cut one of my flowers and stood the stem in a jar, to paint into the hand of an angel. The flower wilted before he finished the gold. He painted the bloom fresh anyway, kinder than the truth. I forgave him." },
        { id = "step", at = 320, title = "The step",
            text = "Later there was a cottage, and a woman who knew a lily must never be moved, so she never moved me. On summer evenings she sat on the step and read aloud to her children. I learned the sound of a story from that step." },
        { id = "wild", at = 450, title = "The wild years",
            text = "The children grew and went, and then the woman too, and the cottage stood empty. Nettles came, and brambles. Year after year I flowered in June for nobody at all. I learned then that I do not flower to be seen. I flower because June asks." },
        { id = "moss", at = 600, title = "Damp moss",
            text = "One autumn someone came through the nettles and lifted a few scales of my bulb, very carefully, as if they knew the old woman's ways. They wrapped me in damp moss and a page torn from an old book. I never saw their face. I never learned what the page said." },
        { id = "deciding", at = 800, title = "Two summers",
            text = "I was planted here, shallow, as a lily should be. Then I did not flower for two summers. Gardeners call that sulking. I call that deciding. A lily does not give her best to a garden she has not yet weighed." },
        { id = "bench", at = 1050, title = "The bench",
            text = "In the third June you sat down beside me with a book and read for an hour without once looking at the time. I had not seen anyone read like that since the monk, and the woman on the step. So I flowered. All at once, every bud." },
        { id = "page", at = 1400, title = "The page",
            text = "{total} pages now, read beside me. I still think about the page that came wrapped round my bulb, the print gone soft with damp. I could never read the thing. Perhaps someone sent me to a reader on purpose. Perhaps that was the message." },
        { id = "remembered", at = 1800, title = "What is handed on",
            text = "One day a scale of me will be lifted and planted in another garden, and that lily will remember, faintly, the painters, the ships, the monk, the step. I have decided what I want remembered most clearly. A bench. A book. You, reading, beside an old white flower who had found her place at last." },
    },
}
